"""geometry.py - simple geometry helpers"""
PI = 3.1416

def circle_area(r):
    return PI * r * r

def rectangle_area(length, width):
    return length * width

def triangle_area(base, height):
    return 0.5 * base * height

if __name__ == "__main__":
    print("Testing geometry module...")
    print(circle_area(1), rectangle_area(2, 3))

def make_student(name, roll, marks):
    return {"name": name, "roll": roll, "marks": marks}

def show(student):
    print(f"{student['roll']}  {student['name']:<8} {student['marks']}")

def average(marks):
    return sum(marks) / len(marks)

def grade(marks):
    if min(marks) < 40:
        return "F"
    avg = average(marks)
    return "A+" if avg >= 80 else "A" if avg >= 60 else "B"

"""fibo.py - Fibonacci helper functions"""

def fib_series(n):
    """Return the first n Fibonacci numbers as a list."""
    series = []
    a, b = 0, 1
    for _ in range(n):
        series.append(a)
        a, b = b, a + b
    return series

def fib_sum(n):
    """Return the sum of the first n Fibonacci numbers."""
    return sum(fib_series(n))
